import mongoose from 'mongoose';

const projectSchema = new mongoose.Schema({
    name: { type: String, required: true, trim: true },
    description: { type: String, required: true, trim: true },
    
    // NEW: ObjectId reference
    createdBy: {
        type: mongoose.Schema.Types.ObjectId,
        ref: "User",
        required: true
    },
    
    // NEW: Proper member structure
    members: [{
        user: { 
            type: mongoose.Schema.Types.ObjectId, 
            ref: "User",
            required: true
        },
        role: { 
            type: String, 
            enum: ["project-lead", "project-member"], 
            default: "project-member"
        },
        joinedAt: { type: Date, default: Date.now }
    }],
    
    // NEW: Task references
    tasks: [{
        type: mongoose.Schema.Types.ObjectId,
        ref: "Task"
    }],
    
    // NEW: Dynamic requirements/attributes
    requirements: [{
        label: { type: String, required: true },
        value: { type: String, required: true },
        createdAt: { type: Date, default: Date.now }
    }],
    
    endDate: { type: Date, required: true },
    status: { type: String, enum: ["active", "completed", "on-hold"], default: "active" },
}, { timestamps: true });

const Project = mongoose.model("Project", projectSchema, "peerCheck_projects");
export default Project;